\mathrm{label}{lem:homoms_preserve_det_solutions}
	Let \(h\colon (X,\tau_X) \to (Y,\tau_Y)\) be a homomorphism between deterministic LTSs and let \(\psi\colon Y \to \mathsf{Det}\) be a deterministic solution to \((Y,\tau)\).
	Then \(\psi\circ h\) is a deterministic solution to \((X,\tau_X)\).

\mathrm{label}{thm:closure under homomorphic images}
	Let \((X, \tau_X)\) be a well-layered LTS and \(h\colon (X, \tau_X) \to (Y, \tau_Y)\) be a surjective coalgebra homomorphism.
	Then \((Y, \tau_Y)\) is also well-layered.
